export const EMPTY_RPN_ROW = (): RpnRow => ({
  incidentName: '',
  causeDetail:  '',
  s: '',
  o: '',
  d: '',
  solution:     '',
});

export function mapDraftRpnRows(rows: MonthlyIncidentReportDraft['rpnRows']): RpnRow[] {
  if (!rows?.length) return [EMPTY_RPN_ROW()];
  return rows.map((r) => ({
    incidentName: r.incidentName ?? '',
    causeDetail:  r.causeDetail  ?? '',
    s: r.s ?? '',
    o: r.o ?? '',
    d: r.d ?? '',
    solution: r.solution ?? '',
  }));
}

export const isNativeMobile = () =>
  typeof navigator !== 'undefined' &&
  /android|iphone|ipad|ipod/i.test(navigator.userAgent);

export function fmtDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}

export function pct(count: number, total: number) {
  if (!total) return '0';
  return ((count / total) * 100).toFixed(1);
}

export function getRpnColor(rpn: number | null) {
  if (rpn === null) return '';
  return rpn >= 200 ? '#dc2626' : rpn >= 100 ? '#f59e0b' : '#10b981';
}

export function getPeriodLabel(filters: MedicalIncidentReportFilters): string {
  if (filters.dateFrom && filters.dateTo) {
    const from = new Date(filters.dateFrom);
    const to   = new Date(filters.dateTo);
    if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
      return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
    return `${from.toLocaleDateString('vi-VN')} – ${to.toLocaleDateString('vi-VN')}`;
  }
  if (filters.year) return `Năm ${filters.year}`;
  return 'Kỳ báo cáo';
}

export type MonthlyCategoryKey = 'clinical' | 'service' | 'fall';

export const MONTHLY_CATEGORY_META: Record<MonthlyCategoryKey, { label: string; shortLabel: string }> = {
  clinical: { label: 'Sự cố liên quan quy trình chuyên môn', shortLabel: 'Quy trình chuyên môn' },
  service:  { label: 'Sự cố liên quan cung cấp nhóm dịch vụ', shortLabel: 'Cung cấp nhóm dịch vụ' },
  fall:     { label: 'Sự cố té ngã', shortLabel: 'Té ngã' },
};

const YES_KEY = 'yes';

function chartYesCount(items: { key: string; count: number }[] | undefined): number | null {
  if (!items?.length) return null;
  const hit = items.find((x) => x.key === YES_KEY);
  return hit ? hit.count : null;
}

export function incidentCategoryCount(item: IncidentReportSummaryItem): number {
  return Number(!!item.isClinical) + Number(!!item.isService) + Number(!!item.isFall);
}

export function isMultiCategoryIncident(item: IncidentReportSummaryItem): boolean {
  return incidentCategoryCount(item) > 1;
}

export function filterSummaryByCategory(
  items: IncidentReportSummaryItem[],
  category: MonthlyCategoryKey,
): IncidentReportSummaryItem[] {
  return items.filter((item) => {
    if (category === 'clinical') return !!item.isClinical;
    if (category === 'service') return !!item.isService;
    return !!item.isFall;
  });
}

export function categoryChips(item: IncidentReportSummaryItem): MonthlyCategoryKey[] {
  const keys: MonthlyCategoryKey[] = [];
  if (item.isClinical) keys.push('clinical');
  if (item.isService) keys.push('service');
  if (item.isFall) keys.push('fall');
  return keys;
}

/**
 * Mục 1.2–1.3 stats shared by editor + print.
 * Each bucket = unique phiếu (đa nhãn). Cấm cộng byIncidentTypeGroup group2–11
 * (một phiếu nhiều nhóm dịch vụ bị đếm nhiều lần — GAP-SCYK-METRIC-08).
 */
export function deriveMonthlySection1Stats(
  report: MedicalIncidentReport,
  summaryItems?: IncidentReportSummaryItem[],
) {
  const groupCount = (key: string) =>
    report.byIncidentTypeGroup.find((x) => x.key === key)?.count ?? 0;

  const voluntaryCount = report.byReportType.find((x) => x.key === 'voluntary')?.count ?? 0;
  const mandatoryCount = report.byReportType.find((x) => x.key === 'mandatory')?.count ?? 0;
  /** SSOT: mọi báo cáo đếm theo Khoa báo cáo (`byReportingDepartment`). */
  const reportingDepartments = report.byReportingDepartment.filter((d) => d.count > 0);

  const hasFlags = !!summaryItems?.some((i) => i.isClinical || i.isService || i.isFall);
  const clinicalFromDto = chartYesCount(report.byRelatedProcess);
  const fallFromDto = chartYesCount(report.byFallIncident);
  const serviceFromDto = chartYesCount(report.byServiceDelivery);

  const clinicalCount = hasFlags
    ? summaryItems!.filter((i) => i.isClinical).length
    : (clinicalFromDto ?? groupCount('group1'));
  const fallCount = hasFlags
    ? summaryItems!.filter((i) => i.isFall).length
    : (fallFromDto ?? groupCount('group7'));
  const serviceCount = hasFlags
    ? summaryItems!.filter((i) => i.isService).length
    : (serviceFromDto ?? 0);

  return {
    voluntaryCount,
    mandatoryCount,
    reportingDepartments,
    clinicalCount,
    serviceCount,
    fallCount,
  };
}
