import React from 'react';
import { Modal } from '@linm-soft-org/linm-web-common-components';
import type { IncidentReportSummaryItem } from '../../../models/MedicalIncident';
import { scykRoutes } from '../../../config/scykRoutes';
import {
  MONTHLY_CATEGORY_META,
  categoryChips,
  isMultiCategoryIncident,
  type MonthlyCategoryKey,
} from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

interface Props {
  category: MonthlyCategoryKey | null;
  items: IncidentReportSummaryItem[];
  onClose: () => void;
}

export const MonthlyReportCategoryDetailModal: React.FC<Props> = ({
  category,
  items,
  onClose,
}) => {
  if (!category) return null;
  const meta = MONTHLY_CATEGORY_META[category];
  const multiCount = items.filter(isMultiCategoryIncident).length;

  return (
    <Modal
      isOpen
      onClose={onClose}
      title={`${meta.label} (${items.length} sự cố)`}
      size="lg"
      data-testid="monthly-report-category-detail-modal"
    >
      <p className={s.categoryModalNote}>
        Danh sách phiếu đã tích nhóm này. Hàng tô vàng thuộc từ 2 nhóm trở lên
        {multiCount > 0 ? ` (${multiCount} phiếu)` : ''}.
      </p>
      {items.length === 0 ? (
        <div className={s.summaryEmpty}>Không có sự cố thuộc nhóm này</div>
      ) : (
        <div className={s.summaryTableWrapper}>
          <table className={s.summaryTable}>
            <thead>
              <tr>
                <th style={{ width: '18%' }}>Khoa báo cáo</th>
                <th style={{ width: '34%' }}>Sự cố / sai sót</th>
                <th style={{ width: '28%' }}>Nhóm</th>
                <th style={{ width: '20%' }}>Mã</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => {
                const multi = isMultiCategoryIncident(item);
                return (
                  <tr
                    key={item.id || `${item.idCode || 'row'}-${idx}`}
                    className={multi ? s.summaryMultiGroupRow : undefined}
                  >
                    <td>{item.departmentName || '—'}</td>
                    <td>{item.briefDescription || item.incidentName || '—'}</td>
                    <td>
                      <span className={s.categoryChipRow}>
                        {categoryChips(item).map((key) => (
                          <span
                            key={key}
                            className={key === category ? s.categoryChipActive : s.categoryChip}
                          >
                            {MONTHLY_CATEGORY_META[key].shortLabel}
                          </span>
                        ))}
                      </span>
                    </td>
                    <td>
                      {item.id ? (
                        <a
                          className={s.categoryDetailLink}
                          href={scykRoutes.incidents.detail(item.id)}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          {item.idCode || 'Xem phiếu'}
                        </a>
                      ) : (
                        item.idCode || '—'
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </Modal>
  );
};
